 1 | // SPDX-License-Identifier: agpl-3.0
 2 | pragma solidity 0.8.9;
 3 | 
 4 | import "./interfaces/external/aave/ILendingPool.sol";
 5 | import "./interfaces/IAaveVaultGovernance.sol";
 6 | import "./Vault.sol";
 7 | import "./libraries/ExceptionsLibrary.sol";
 8 | 
 9 | /// @notice Vault that interfaces Aave protocol in the integration layer.
10 | /// @dev Notes:
11 | /// ### TVL
12 | ///
13 | /// The TVL of the vault is cached and updated after each deposit withdraw.
14 | /// So essentially `tvl` call doesn't take into account accrued interest / donations to Aave since the
15 | /// last `deposit` / `withdraw`
16 | ///
17 | /// ### aTokens
18 | /// aTokens are fixed at the token creation and addresses are taken from Aave Lending Pool.
19 | /// So essentially each aToken is fixed for life of the AaveVault. If the aToken is missing for some vaultToken,
20 | /// the AaveVault cannot be created.
21 | ///
22 | /// ### Push / Pull
23 | /// It is assumed that any amounts of tokens can be deposited / withdrawn from Aave.
24 | /// The contract's vaultTokens are fully allowed to Aave Lending Pool.
25 | contract AaveVault is Vault {
26 |     address[] internal _aTokens;
27 |     uint256[] internal _tvls;
28 | 
29 |     /// @notice Creates a new contract.
30 |     /// @dev Requires that aToken exists for each vaultToken
31 |     /// @param vaultGovernance_ Reference to VaultGovernance for this vault
32 |     /// @param vaultTokens_ ERC20 tokens under Vault management
33 |     constructor(IVaultGovernance vaultGovernance_, address[] memory vaultTokens_)
34 |         Vault(vaultGovernance_, vaultTokens_)
35 |     {
36 |         _aTokens = new address[](vaultTokens_.length);
37 |         for (uint256 i = 0; i < _vaultTokens.length; i++) {
38 |             address aToken = _getAToken(_vaultTokens[i]);
39 |             require(aToken != address(0), ExceptionsLibrary.ZERO_TOKEN);
40 |             _aTokens[i] = aToken;
41 |             _tvls.push(0);
42 |         }
43 |     }
44 | 
45 |     /// @inheritdoc Vault
46 |     function tvl() public view override returns (uint256[] memory tokenAmounts) {
47 |         return _tvls;
48 |     }
49 | 
50 |     /// @notice Update all tvls to current aToken balances.
51 |     function updateTvls() public {
52 |         for (uint256 i = 0; i < _tvls.length; i++) {
